  onPanelOption(event) {
    const { themeid, index } = event.currentTarget.dataset;
    const panel = this.getPanel(themeid);
    if (!panel || panel.isLoading || panel.ending) {
      return;
    }
    const optionIndex = Number(index);
    if (Number.isNaN(optionIndex)) {
      return;
