    const userSelectionSummary =
      selectedOption === 4 && normalizedCustomText
        ? `${option4Prefix}${normalizedCustomText}`
        : `玩家选择了选项 ${selectedOption}`;

    const userMessage = { role: 'user', content: userSelectionSummary } as SessionMessage;
